use crate::common;
use rust_xlsxwriter::{Format, Workbook, XlsxError};

// Create a rust_xlsxwriter file to compare against an Excel file.
fn create_new_xlsx_file(filename: &str) -> Result<(), XlsxError> {
    let mut workbook = Workbook::new();

    let worksheet = workbook.add_worksheet();

    let format1 = Format::new().set_font_name("a_x0041_b").set_font_family(0);
    let format2 = Format::new().set_num_format("0.0\" a_x0041_b\"");

    worksheet.set_column_autofit_width(0, 93)?;
    worksheet.write_with_format(0, 0, "Hello", &format1)?;
    worksheet.write_with_format(1, 0, 1.5, &format2)?;

    workbook.save(filename)?;

    Ok(())
}

#[test]
fn test_escapes12() {
    let test_runner = common::TestRunner::new()
        .set_name("escapes12")
        .set_function(create_new_xlsx_file)
        .initialize();

    test_runner.assert_eq();
    test_runner.cleanup();
}
